import json
from typing import Any

def _validate(records: Any) -> list[dict[str, object]]:
    if not isinstance(records, list):
        raise ValueError('assignment data must be a list')
    result = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each assignment must be an object')
        if any((field not in record for field in ('employee_id', 'asset_tag', 'status'))):
            raise ValueError('assignment fields are missing')
        if not all((isinstance(record[field], str) for field in ('employee_id', 'asset_tag', 'status'))):
            raise ValueError('assignment fields must be strings')
        result.append(dict(record))
    return result

def serialize_assignments(assignments: list[dict[str, object]]) -> bytes:
    records = _validate(assignments)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def restore_assignments(payload: bytes) -> list[dict[str, object]]:
    try:
        records = _validate(json.loads(payload.decode('utf-8')))
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError, TypeError, ValueError) as exc:
        raise ValueError('invalid assignment payload') from exc
    return sorted((record for record in records if record['status'] == 'assigned'), key=lambda record: record['asset_tag'])

