        raise ValueError('invalid state')
    bookings = state.get('bookings')
    if not isinstance(bookings, list):
        raise ValueError('invalid bookings')
    for booking in bookings:
        if not isinstance(booking, dict):
            raise ValueError('invalid booking')
        if not isinstance(booking.get('event'), str) or not isinstance(booking.get('date'), str):
            raise ValueError('invalid booking')
        guests = booking.get('guests')
        if isinstance(guests, bool) or not isinstance(guests, int) or guests < 0:
            raise ValueError('invalid guest count')

def encode_booking_state(state: dict) -> bytes:
    _validate_state(state)
    return json.dumps(state, sort_keys=True, separators=(',', ':')).encode('utf-8')

def decode_booking_state(payload: bytes) -> dict:
    try:
        if not isinstance(payload, bytes):
            raise ValueError('invalid payload')
        state = json.loads(payload.decode('utf-8'))
        _validate_state(state)
        return state
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError) as exc:
