import datetime
import json

def _normalise(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    result = []
    for record in records:
        if not isinstance(record, dict) or set(record) != {'case_id', 'deadline'}:
            raise ValueError('invalid record')
        case_id = record['case_id']
        deadline = record['deadline']
        if not isinstance(case_id, str) or not isinstance(deadline, str):
            raise ValueError('invalid record')
        try:
            datetime.date.fromisoformat(deadline)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        result.append({'case_id': case_id, 'deadline': deadline})
    return sorted(result, key=lambda item: (item['deadline'], item['case_id']))

def pack_deadlines(deadlines: list[dict[str, str]]) -> bytes:
    records = _normalise(deadlines)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def unpack_deadlines(payload: bytes) -> list[dict[str, str]]:
    try:
        records = json.loads(payload.decode('utf-8'))
        return _normalise(records)
    except (UnicodeError, json.JSONDecodeError, TypeError, AttributeError, ValueError) as exc:
        if isinstance(exc, ValueError) and str(exc) in {'invalid record', 'invalid date', 'records must be a list'}:
            raise
        raise ValueError('malformed payload') from exc

