import json
import urllib.parse
import urllib.request

def fetch_settled_amount(api_url: str, merchant_id: str) -> int:
    if not merchant_id:
        raise ValueError('merchant_id must not be empty')
    url = api_url + '?merchant_id=' + urllib.parse.quote(merchant_id, safe='')
    with urllib.request.urlopen(url) as response:
        payload = json.loads(response.read())
    return sum((item['amount_cents'] for item in payload['settlements'] if item['merchant_id'] == merchant_id and item['status'] == 'settled'))

