import html

def render_purchase_order(order_id: str, supplier: str, items: list[tuple[str, int, float]]) -> str:
    for name, quantity, price in items:
        if quantity < 1 or price < 0:
            raise ValueError('invalid item')
    rows = []
    total = 0.0
    for name, quantity, price in sorted(items, key=lambda item: item[0]):
        formatted_price = f'{price:.2f}'
