import urllib.request

def get_eligible_programs(postal_code: str, annual_income: int) -> list[str]:
    if not postal_code or annual_income < 0:
        raise ValueError('invalid eligibility request')
    url = f'https://benefits.example.gov/eligibility?postal_code={postal_code}'
    with urllib.request.urlopen(url) as response:
        data = json.loads(response.read().decode('utf-8'))
    names = [program['name'] for program in data['programs'] if program['income_limit'] >= annual_income]
    return sorted(names)

